import{c as e,Q as a,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"The Loop 徹底正典化 + 全 workspace 一致性稽核 — Session Insight 報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-06-the-loop-canonicalization-and-audit-insights.md","filePath":"research/reports/archive/2026-06-06-the-loop-canonicalization-and-audit-insights.md","lastUpdated":1785909234000}'),r={name:"research/reports/archive/2026-06-06-the-loop-canonicalization-and-audit-insights.md"};function i(n,t,d,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="the-loop-徹底正典化-全-workspace-一致性稽核-—-session-insight-報告" tabindex="-1">The Loop 徹底正典化 + 全 workspace 一致性稽核 — Session Insight 報告 <a class="header-anchor" href="#the-loop-徹底正典化-全-workspace-一致性稽核-—-session-insight-報告" aria-label="Permalink to &quot;The Loop 徹底正典化 + 全 workspace 一致性稽核 — Session Insight 報告&quot;">​</a></h1><blockquote><p><strong>產出日期</strong>：2026-06-06 <strong>承接</strong>：<code>2026-06-06-zeuik-workspace-canon.md</code>（#484，The Loop 六階段重構 + §Rn 保留為 tag 階段） <strong>涵蓋 commit</strong>：#484 → #485（徹底退役 §Rn）→ 2 次稽核收尾（9f715b70 / 0f06cb79）→ pilot 死鏈修復（623c99c1） <strong>定位</strong>：本報告記錄「<strong>§Rn 從保留-as-tag 到徹底退役</strong>」的完整決策反轉 + 全 workspace 一致性稽核的方法論教訓 + cold start 歸因 + SKILL 可執行性稽核。聚焦<strong>會重演的失敗模式</strong>，非流水帳。前作記「重構怎麼設計」，本作記「徹底化怎麼安全執行 + 稽核怎麼不漏」。</p></blockquote><hr><h2 id="_0-一句話總結" tabindex="-1">0. 一句話總結 <a class="header-anchor" href="#_0-一句話總結" aria-label="Permalink to &quot;0. 一句話總結&quot;">​</a></h2><p>#484 把 The Loop 設為主敘事但<strong>保留 §Rn 為 inline tag</strong>（保守，怕破 1,788 處引用）；使用者隨後要求<strong>徹底退役 §Rn</strong>（維護負擔）→ 本 session 完成反轉，並在過程中發現「徹底化」比「保留」更危險的盲點：<strong>移除 tag 會把上次刻意保留的引用全部變成真死指針</strong>——這是與前一階段策略完全相反的 cascade。</p><hr><h2 id="_1-核心決策反轉-保留-as-tag-→-徹底退役" tabindex="-1">1. 核心決策反轉：保留-as-tag → 徹底退役 <a class="header-anchor" href="#_1-核心決策反轉-保留-as-tag-→-徹底退役" aria-label="Permalink to &quot;1. 核心決策反轉：保留-as-tag → 徹底退役&quot;">​</a></h2><h3 id="_1-1-為何反轉是對的" tabindex="-1">1.1 為何反轉是對的 <a class="header-anchor" href="#_1-1-為何反轉是對的" aria-label="Permalink to &quot;1.1 為何反轉是對的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#484 階段（保留 tag）</th><th>本 session（徹底退役）</th><th>反轉理由</th></tr></thead><tbody><tr><td>§Rn 降為 inline <code>〔§Rn〕</code> tag，保留 1,788 處引用可解析</td><td>徹底移除 tag，§Rn 只在 attribution 句存活</td><td>使用者明說「一直用 Rn tag 對維護是麻煩」</td></tr><tr><td>gate 驗「§R inline tag ≥11」</td><td>gate 驗六階段 header + Token Budget anchor</td><td>tag 沒了，斷言要換錨點</td></tr><tr><td>best-solution 保留 12 R-section</td><td>best-solution 重寫六階段詳解</td><td>「12 條 canonical」與「The Loop 主敘事」並存造成兩套真理</td></tr></tbody></table><p><strong>官方依據</strong>（#484 已查證）：官方只要求「markdown header 分組」，從不要求 §Rn 編號——編號是 Karpathy/Mnilax 慣例。徹底退役不違反官方。</p><h3 id="_1-2-反轉的代價-inverse-cascade-本報告最重要的教訓" tabindex="-1">1.2 反轉的代價：inverse cascade（本報告最重要的教訓） <a class="header-anchor" href="#_1-2-反轉的代價-inverse-cascade-本報告最重要的教訓" aria-label="Permalink to &quot;1.2 反轉的代價：inverse cascade（本報告最重要的教訓）&quot;">​</a></h3><blockquote><p><strong>Lesson — 移除「上次刻意保留的相容層」會把所有依賴它的引用一次性變成死指針。</strong></p></blockquote><p>#484 的策略是「保留 §Rn tag 讓 <code>core §R8</code> 仍可 grep 命中」。本 session 刪掉 tag 後，<strong>所有那些被刻意保留的 bare <code>§Rn</code> / <code>§Rn.x</code> 引用瞬間全部失效</strong>——這是與前一階段完全相反的方向。</p><p>具體：<code>§R12.1</code>/<code>§R4.1</code> 等子編號在 #484 時還能靠 §R12 tag 部分解析，徹底退役後是 100% 死指針。harness-meta-GOTCHAS 的 4 處子編號、pilot 的 <code>core.md § &quot;Think-Before-Coding&quot;</code>、CLAUDE.md/README 的「§Rn inline tag」描述全部變 stale。</p><p><strong>防範</strong>：移除任何「為相容而保留的層」前，先 grep 全部依賴它的引用，列為同批 scope。不能假設「上次保留了 = 這次移除安全」——恰恰相反，保留層的移除是最高風險的 cascade。</p><hr><h2 id="_2-一致性稽核的方法論教訓-4-次掃描才收斂" tabindex="-1">2. 一致性稽核的方法論教訓（4 次掃描才收斂） <a class="header-anchor" href="#_2-一致性稽核的方法論教訓-4-次掃描才收斂" aria-label="Permalink to &quot;2. 一致性稽核的方法論教訓（4 次掃描才收斂）&quot;">​</a></h2><h3 id="_2-1-失敗模式-3-次「exhaustive」掃描都漏" tabindex="-1">2.1 失敗模式：3 次「exhaustive」掃描都漏 <a class="header-anchor" href="#_2-1-失敗模式-3-次「exhaustive」掃描都漏" aria-label="Permalink to &quot;2.1 失敗模式：3 次「exhaustive」掃描都漏&quot;">​</a></h3><p>本 session 對「§Rn / 12 準則殘留」做了至少 4 輪掃描。前 3 輪都宣告「§Rn = 0」，第 4 輪又找到 2-3 個。根因有二：</p><p><strong>根因 A — grep pattern 不涵蓋變體</strong>：</p><ul><li>前幾輪只 grep <code>§R[0-9]</code> + 英文 <code>12-Rule</code>。</li><li>漏掉：<code>R5-R12</code> / <code>R13</code> / <code>R14</code> / <code>14 條</code> / <code>14-rule</code> / <code>Rule 5</code> / 中文 <code>12 條準則</code> / <code>core.md § &quot;&lt;概念名&gt;&quot;</code>（措辭引用非 section 名）。</li><li>→ 每輪都「在自己定義的窄 pattern 內掃乾淨」，但 pattern 本身漏。</li></ul><p><strong>根因 B — <code>grep -v &#39;research/&#39;</code> 子字串過濾脆弱</strong>：</p><ul><li>chained <code>grep -v</code> 對大輸出（87KB）行為不穩，substring 匹配非 path-anchor，第 1-2 次過濾失效，第 3 次才對。</li><li>→ 大輸出時改「寫小檔再讀」或 <code>awk -F:</code> path-field 過濾，不靠 chained grep -v。</li></ul><h3 id="_2-2-正解-canonical-sweep-eyeball-不-drive-to-0" tabindex="-1">2.2 正解：canonical sweep + eyeball（不 drive-to-0） <a class="header-anchor" href="#_2-2-正解-canonical-sweep-eyeball-不-drive-to-0" aria-label="Permalink to &quot;2.2 正解：canonical sweep + eyeball（不 drive-to-0）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rnE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;§R[0-9]|〔§R|R1[-–]R12|R5[-–]R12|R1[34]|1[24][ -]?[Rr]ule|1[24] 條準則&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*.md&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*.sh&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*.yml&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*.py&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;*.json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/sweep.txt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 過濾 research/memory/log 後寫小檔，逐個 eyeball</span></span></code></pre></div><blockquote><p><strong>Lesson — 稽核「該保留的東西」時，count-based check 是錯的；必須逐個 eyeball 區分 attribution vs pointer。</strong></p></blockquote><p>關鍵 discriminator：</p><ul><li><strong>attribution / lineage</strong>（保留）：「Karpathy R1-R4 + Mnilax R5-R12 為參考基礎」「Mnilax 以 R5-R12 回應」</li><li><strong>structural pointer</strong>（修）：「core.md 的 §R8」「見 §R5」「§Rn inline tag」（描述已不存在的結構）</li><li><strong>獨立文件</strong>（保留）：<code>ai-coding-agent-guidelines.md</code>（Author-B 的獨立 R1-R14 體系，非 workspace 鏡像）</li></ul><p>「drive grep to 0」在這裡是錯的——因為 attribution 句必須存活。只有逐個 eyeball 能回答「12 準則還有沒有殘留」。</p><h3 id="_2-3-sub-agent-worktree-隔離再次應驗" tabindex="-1">2.3 sub-agent worktree 隔離再次應驗 <a class="header-anchor" href="#_2-3-sub-agent-worktree-隔離再次應驗" aria-label="Permalink to &quot;2.3 sub-agent worktree 隔離再次應驗&quot;">​</a></h3><p>委派 implementer 改 §Rn 引用時，agent 在隔離 worktree 工作，<strong>產物不在主 tree</strong>（Lesson 2026-06-04-C 應驗）。主對話 grep 主 tree 發現 18 處 §Rn 仍在 → 從 worktree cp 回 8 檔 → 移除 worktree。</p><blockquote><p><strong>防範（已知 lesson 再確認）</strong>：委派建檔/改檔後必 grep 主 tree；不在則從 <code>worktreePath</code> 取回。agent 回報「完成」是 unverified_success，主對話親驗才算。</p></blockquote><hr><h2 id="_3-research-連結的三類處理-脫離-workspace-可運作" tabindex="-1">3. research/ 連結的三類處理（脫離 workspace 可運作） <a class="header-anchor" href="#_3-research-連結的三類處理-脫離-workspace-可運作" aria-label="Permalink to &quot;3. research/ 連結的三類處理（脫離 workspace 可運作）&quot;">​</a></h2><p>使用者要求：SKILL 取用 research/ 改成 <strong>prompt 行為驅動</strong>（脫離 workspace 仍可運作），不是死路徑。</p><h3 id="_3-1-關鍵區分-a-類不能改-會壞-skill-核心功能" tabindex="-1">3.1 關鍵區分：A 類不能改（會壞 SKILL 核心功能） <a class="header-anchor" href="#_3-1-關鍵區分-a-類不能改-會壞-skill-核心功能" aria-label="Permalink to &quot;3.1 關鍵區分：A 類不能改（會壞 SKILL 核心功能）&quot;">​</a></h3><blockquote><p><strong>Lesson — research/ 連結不是都該清；輸出路徑（A 類）是 SKILL 的功能，誤清會壞 resume/歸檔。</strong></p></blockquote><table tabindex="0"><thead><tr><th>類</th><th>判別</th><th>處理</th><th>例</th></tr></thead><tbody><tr><td><strong>A — I/O 輸出路徑</strong></td><td>bash 命令 / 變數賦值 / <code>mkdir -p</code> / <code>REPORT_PATH=</code></td><td><strong>保留</strong></td><td>overnight-research 寫 <code>research/scratch/source-N.md</code>（deterministic 命名，resume 依賴）</td></tr><tr><td><strong>B — 讀依賴</strong></td><td>「理論基礎/詳見/依據 research/X」要讀才能運作</td><td><strong>改 prompt 降級</strong></td><td>「若 workspace 有則搜尋，無則依一般原則」</td></tr><tr><td><strong>C — 純引用標註</strong></td><td>「來源：research/X」只標出處</td><td><strong>軟化去路徑</strong></td><td>「@Mnilax（workspace 歸檔）」</td></tr></tbody></table><p>A 類誤改成「動態推斷輸出路徑」會破壞 overnight-research 的 source-N.md deterministic 命名 + grep-back verify。<strong>用 AskUserQuestion 確認範圍邊界</strong>（A 保留 vs 全改），不自決——因為 A 誤改不可逆且壞功能。</p><h3 id="_3-2-prompt-降級的正確措辭" tabindex="-1">3.2 prompt 降級的正確措辭 <a class="header-anchor" href="#_3-2-prompt-降級的正確措辭" aria-label="Permalink to &quot;3.2 prompt 降級的正確措辭&quot;">​</a></h3><p>死連結 <code>理論基礎：research/X.md</code> → 改成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理論基礎：若 workspace 有研究歸檔則搜尋參照（grep research/...）；</span></span>
<span class="line"><span>脫離 workspace 時依本檔摘要 + 一般原則</span></span></code></pre></div><p>zeuik-senior-architect（整個 agent 靠 career-wiki 運作）→ 加「脫離 workspace 降級：基於 CLAUDE.md 職涯背景 + 一般經驗，明確標註『無 career-wiki 細節』，不杜撰」。</p><p>→ 這讓 SKILL「有 workspace 用 workspace，沒有也能降級運作 + 誠實標註」，而非留死指針。</p><hr><h2 id="_4-cold-start-歸因-誠實-差點報錯" tabindex="-1">4. Cold Start 歸因（誠實，差點報錯） <a class="header-anchor" href="#_4-cold-start-歸因-誠實-差點報錯" aria-label="Permalink to &quot;4. Cold Start 歸因（誠實，差點報錯）&quot;">​</a></h2><p>使用者問「cold start 是否也有改善」。<strong>差點報錯 +2,060 byte，advisor 攔下修正為 +390</strong>。</p><h3 id="_4-1-byte-歸因的陷阱" tabindex="-1">4.1 byte 歸因的陷阱 <a class="header-anchor" href="#_4-1-byte-歸因的陷阱" aria-label="Permalink to &quot;4.1 byte 歸因的陷阱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>數字</th><th>含義</th></tr></thead><tbody><tr><td>16,927（06-03 baseline）→ 18,987（#484 後）= +2,060</td><td>❌ 我差點說「The Loop 重寫造成」</td></tr><tr><td>18,597（本 session 起始，已含 #483）→ 18,987 = <strong>+390</strong></td><td>✅ The Loop 重寫<strong>實際貢獻</strong></td></tr><tr><td>16,927 → 18,597 的 +1,670</td><td>#483 等<strong>本 session 前</strong>的 commit，與重寫無關</td></tr></tbody></table><blockquote><p><strong>Lesson — 量測「我的改動造成的 delta」要用 session 起始值，不是 N 天前的 baseline。</strong> 拿 3 天前 baseline 比，會把中間所有 commit 的累積都算到我頭上，5× 高估。</p></blockquote><h3 id="_4-2-誠實結論" tabindex="-1">4.2 誠實結論 <a class="header-anchor" href="#_4-2-誠實結論" aria-label="Permalink to &quot;4.2 誠實結論&quot;">​</a></h3><ul><li>The Loop 重寫對 cold start <strong>淨影響可忽略</strong>（+390 byte，cache 後不重算；徹底退役 §Rn 後反而降到 18,726）。</li><li>healthcheck +857ms 全是 #483 的 §15/§16 + 每日 GHA，<strong>與重寫無關</strong>。</li><li>06-03 報告核心結論仍成立：<strong>瓶頸從來不在 auto-load byte，在 hook spawn + 同步 healthcheck</strong>。想改善看 06-03 action-plan 的 <code>async:true</code> 槓桿（未執行），不在 auto-load。</li></ul><hr><h2 id="_5-skill-可執行性稽核-27-skill" tabindex="-1">5. SKILL 可執行性稽核（27 SKILL） <a class="header-anchor" href="#_5-skill-可執行性稽核-27-skill" aria-label="Permalink to &quot;5. SKILL 可執行性稽核（27 SKILL）&quot;">​</a></h2><h3 id="_5-1-「正常執行」的分層檢查" tabindex="-1">5.1 「正常執行」的分層檢查 <a class="header-anchor" href="#_5-1-「正常執行」的分層檢查" aria-label="Permalink to &quot;5.1 「正常執行」的分層檢查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>層</th><th>方法</th><th>結果</th></tr></thead><tbody><tr><td>結構完整</td><td>SKILL.md + name/description frontmatter</td><td>27/27 ✅</td></tr><tr><td>scripts 語法</td><td><code>bash -n</code> + <code>py_compile</code></td><td>全過 ✅</td></tr><tr><td>references 斷裂</td><td>grep references/*.md 引用 vs 實體</td><td>0 斷裂 ✅</td></tr><tr><td>RESOLVER 一致</td><td>healthcheck §15 雙向</td><td>✅</td></tr><tr><td>語意執行性</td><td>sub-agent 審改動 SKILL + 主對話親驗</td><td>發現 pilot 死鏈</td></tr></tbody></table><h3 id="_5-2-發現的-pilot-死鏈" tabindex="-1">5.2 發現的 pilot 死鏈 <a class="header-anchor" href="#_5-2-發現的-pilot-死鏈" aria-label="Permalink to &quot;5.2 發現的 pilot 死鏈&quot;">​</a></h3><blockquote><p><strong>Lesson — 大重構後，SKILL 內「指向 core.md 具名 section 的 citation」是隱性死鏈，grep <code>§Rn</code> 抓不到。</strong></p></blockquote><p>3 個 pilot SKILL 引用 <code>core.md § &quot;Think-Before-Coding&quot;</code> / <code>&quot;Surgical Changes&quot;</code> / <code>commit atomicity</code>——core.md 改六階段後這些<strong>具名子節不存在</strong>（折進 IDENTIFY/PROPOSE）。這類死鏈：</p><ul><li>不含 <code>§Rn</code>，純概念名引用 → R-form sweep 抓不到。</li><li>不影響執行（敘述性 citation 非 bash），但讀者/sub-agent 按引用找原文會失敗。</li><li>修法：<code>§ &quot;Think-Before-Coding&quot;</code> → <code>IDENTIFY 段</code>、<code>§ &quot;Surgical Changes&quot;</code> → <code>PROPOSE 段</code>。</li></ul><p>→ 稽核大重構的死鏈，除了 <code>§Rn</code> 還要掃 <code>core.md § &quot;&lt;概念名&gt;&quot;</code> 變體。</p><hr><h2 id="_6-誠實聲明-「正常執行」的範圍" tabindex="-1">6. 誠實聲明（「正常執行」的範圍） <a class="header-anchor" href="#_6-誠實聲明-「正常執行」的範圍" aria-label="Permalink to &quot;6. 誠實聲明（「正常執行」的範圍）&quot;">​</a></h2><p>本 session 的 SKILL 稽核是<strong>靜態可執行性</strong>（結構/語法/引用完整/邏輯連貫），<strong>不是逐個端到端實跑</strong>——多數 SKILL 需外部資源（MCP/web/API），無法全在單 session 實測。我改動觸及的 SKILL 的核心 bash 斷言（verified-merge re-fetch、autoload-evolution value-check）有實際跑。</p><hr><h2 id="_7-可操作教訓萃取-給未來的稽核" tabindex="-1">7. 可操作教訓萃取（給未來的稽核） <a class="header-anchor" href="#_7-可操作教訓萃取-給未來的稽核" aria-label="Permalink to &quot;7. 可操作教訓萃取（給未來的稽核）&quot;">​</a></h2><ol><li><strong>移除相容層前先 grep 全部依賴它的引用</strong>（inverse cascade，§1.2）。</li><li><strong>稽核「該保留的東西」用 canonical sweep + eyeball，不 drive-to-0</strong>（attribution vs pointer，§2.2）。</li><li><strong>grep pattern 要涵蓋全變體</strong>（§Rn / R5-R12 / R13/R14 / 14條 / <code>§ &quot;&lt;概念名&gt;&quot;</code>），大輸出寫小檔再讀（§2.1）。</li><li><strong>委派改檔後必 grep 主 tree + worktree 取回</strong>（§2.3）。</li><li><strong>research/ 連結三類處理，A 類輸出路徑保留</strong>，範圍邊界用 AskUserQuestion（§3）。</li><li><strong>量測自己改動的 delta 用 session 起始值，非舊 baseline</strong>（§4.1）。</li><li><strong>大重構後掃 SKILL 的 <code>core.md § &quot;&lt;概念名&gt;&quot;</code> 死鏈</strong>（§5.2）。</li></ol><hr><h2 id="_8-最終狀態-機械驗證" tabindex="-1">8. 最終狀態（機械驗證） <a class="header-anchor" href="#_8-最終狀態-機械驗證" aria-label="Permalink to &quot;8. 最終狀態（機械驗證）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>值</th></tr></thead><tbody><tr><td>active §Rn</td><td>0</td></tr><tr><td>12-Rule 主結構描述</td><td>0</td></tr><tr><td>best-solution</td><td>六階段 self-contained（research/=0）</td></tr><tr><td>auto-load byte</td><td>18,726 ≤ 19,000</td></tr><tr><td>27 SKILL</td><td>全部靜態可執行</td></tr><tr><td>gate / healthcheck</td><td>green / 116 FAIL 0</td></tr><tr><td>research/ 死連結（active 非 A 類）</td><td>0（B 改 prompt / C 軟化）</td></tr></tbody></table><hr><p><em>本報告為 session insight 沉澱。決策設計見 <code>2026-06-06-zeuik-workspace-canon.md</code>。原始 §Rn 對應見 git 歷史。</em></p>`,72)])])}const k=e(r,[["render",i]]);export{g as __pageData,k as default};
